	/** Task for off-loading long-running Sync operation */
	private class SyncTask : Task {

		private DataTypeSynchronizer synchronizer;

		public SyncTask(DataTypeSynchronizer synchronizer) : base("Data Type Sync - " + getOperationName(), true, true, true)
    {
			this.synchronizer = synchronizer;
		}

		/* @Override */
		public void run(TaskMonitor monitor) {
			doSync(synchronizer, monitor);
		}

	}

}
